class Solution:
    def canCompleteCircuit(self, gas, cost):
        if sum(gas) < sum(cost):
            return -1
        start = tank = 0
        for i in range(len(gas)):
            tank += gas[i] - cost[i]
            if tank < 0:          # cannot reach i+1 from `start` (nor from anything in between)
                start = i + 1
                tank = 0
        return start

