class Solution:
    def mergeTriplets(self, triplets, target):
        x, y, z = target
        got = [False, False, False]
        for a, b, c in triplets:
            if a > x or b > y or c > z:
                continue          # using this triplet would overshoot forever
            got[0] |= a == x
            got[1] |= b == y
            got[2] |= c == z
        return all(got)

