class Solution:
    def checkValidString(self, s):
        lo = hi = 0     # min / max possible number of unmatched '('
        for ch in s:
            if ch == "(":
                lo += 1; hi += 1
            elif ch == ")":
                lo -= 1; hi -= 1
            else:
                lo -= 1; hi += 1
            if hi < 0:          # too many ')' even if every * is '('
                return False
            lo = max(lo, 0)     # a negative count is never a real choice
        return lo == 0

