class Solution:
    def lemonadeChange(self, bills):
        fives = tens = 0
        for b in bills:
            if b == 5:
                fives += 1
            elif b == 10:
                if not fives:
                    return False
                fives -= 1; tens += 1
            else:
                if tens and fives:          # prefer spending the less flexible $10
                    tens -= 1; fives -= 1
                elif fives >= 3:
                    fives -= 3
                else:
                    return False
        return True

