class Solution:
    def candy(self, ratings):
        n = len(ratings)
        c = [1] * n
        for i in range(1, n):                 # satisfy the left-neighbour rule
            if ratings[i] > ratings[i - 1]:
                c[i] = c[i - 1] + 1
        for i in range(n - 2, -1, -1):        # satisfy the right-neighbour rule
            if ratings[i] > ratings[i + 1]:
                c[i] = max(c[i], c[i + 1] + 1)
        return sum(c)

