count-primes.solution:
class Solution:
    def countPrimes(self, n):
        if n < 3:
            return 0
        is_p = bytearray([1]) * n
        is_p[0] = is_p[1] = 0
        i = 2
        while i * i < n:
            if is_p[i]:
                # cross off i*i, i*i + i, ... (smaller multiples were crossed by smaller primes)
                is_p[i * i:n:i] = bytes(len(range(i * i, n, i)))
            i += 1
        return sum(is_p)

