class Solution:
    def gcdAndLcm(self, nums):
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a
        g = l = nums[0]
        for x in nums[1:]:
            g = gcd(g, x)
            l = l // gcd(l, x) * x        # divide first to keep numbers small
        return [g, l]

