class Solution:
    def carPooling(self, trips, capacity):
        change = [0] * 1001               # change[x] = net passengers boarding at kilometre x
        for people, start, end in trips:
            change[start] += people
            change[end] -= people
        load = 0
        for delta in change:
            load += delta
            if load > capacity:
                return False
        return True

