single-number-ii.solution:
class Solution:
    def singleNumber(self, nums):
        result = 0
        for k in range(32):
            ones = sum((x >> k) & 1 for x in nums)   # how many numbers have bit k set
            if ones % 3:
                result |= 1 << k
        if result >= 1 << 31:                        # bit 31 set: negative in 32-bit two's complement
            result -= 1 << 32
        return result

