single-number-iii.solution:
class Solution:
    def singleNumber(self, nums):
        both = 0
        for x in nums:
            both ^= x                 # both == a ^ b
        low = both & -both            # one bit position where a and b differ
        a = 0
        for x in nums:
            if x & low:               # the group that has this bit set contains exactly one of them
                a ^= x
        return [a, a ^ both]

