hamming-distance.solution:
class Solution:
    def hammingDistance(self, x, y):
        diff = x ^ y              # 1 exactly where the two numbers differ
        count = 0
        while diff:
            diff &= diff - 1      # remove one differing bit
            count += 1
        return count

