utf-8-validation.solution:
class Solution:
    def validUtf8(self, data):
        need = 0                              # continuation bytes still expected
        for byte in data:
            byte &= 0xFF
            if need:
                if byte >> 6 != 0b10:         # must look like 10xxxxxx
                    return False
                need -= 1
            elif byte >> 7 == 0:              # 0xxxxxxx
                need = 0
            elif byte >> 5 == 0b110:
                need = 1
            elif byte >> 4 == 0b1110:
                need = 2
            elif byte >> 3 == 0b11110:
                need = 3
            else:                             # 10xxxxxx as a first byte, or 11111xxx
                return False
        return need == 0

